---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Reasoning trail: The agent's plan, notes, sources and edits, after it thinks.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change reasoning-trail.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './reasoning-trail.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="reasoning-trail" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="rtr-dm dm"><div class="dm-main"><div class="rtr panel mx-grow">
  <button class="rtr-h mx-press" aria-expanded="true">
    <span class="think on rtr-mark"><i></i><i></i><i></i><i></i></span>
    <span class="rtr-title shim">Reasoning</span><span class="rtr-time num muted">0s</span>
    <svg class="i xs rtr-chev"><use href="#i-chev-d"/></svg>
  </button>
  <div class="fold rtr-fold"><div>
    <div class="rtr-body"></div>
    <div class="fold rtr-ff shut"><div><p class="rtr-f"><span class="rtr-fk" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m5 12.5 4.5 4.5L19 7.5"/></svg></span><span class="rtr-fd"></span><span class="rtr-fs"></span></p></div></div>
  </div></div>
</div></div>
  <div class="demo"><div class="seg2" role="group" aria-label="View"><button aria-pressed="true" data-v="plan">Plan</button><button aria-pressed="false" data-v="notes">Notes</button><button aria-pressed="false" data-v="sources">Sources</button><button aria-pressed="false" data-v="edits">Edits</button></div></div>
</div>
  </Fragment></div>
</div>
<script>
  import './reasoning-trail.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Reasoning trail ---------- */
.rtr{width:100%;padding:6px}
.rtr-h{display:flex;align-items:center;gap:10px;width:100%;padding:10px var(--dm-s-3);border-radius:var(--dm-r-in);font-size:13.5px;transition:background .2s}
@media (hover:hover) and (pointer:fine){.rtr-h:hover{background:var(--dm-row)}}
/* its motion (the core's motion pieces, owner, 26 Nov): a press on the header shows at once (.mx-press); in Clean the card grows on
   the spring (.mx-grow) */
.rtr-mark{color:var(--dm-fg2)}
.rtr-chev{margin-left:auto;color:var(--dm-muted);transition:transform .4s var(--dm-ease)}
.rtr-h[aria-expanded="false"] .rtr-chev{transform:rotate(-90deg)}
.rtr-body{padding:var(--dm-s-1) var(--dm-s-3) 10px}
.rtr-li{position:relative;display:flex;gap:10px;padding:6px 0 6px var(--dm-s-6);font-size:13.5px;color:var(--dm-fg2)}
.rtr-li .g{position:absolute;left:0;top:7px;width:16px;height:16px;display:grid;place-items:center;color:var(--dm-muted)}
.rtr-li:not(:last-child)::before{content:"";position:absolute;left:7.5px;top:25px;bottom:-6px;width:1px;background:var(--dm-rail)}
.rtr-li .d{display:block;font-size:12px;color:var(--dm-muted);margin-top:1px}
.rtr-li.now{color:var(--dm-fg)}
.rtr-edit{font-family:var(--dm-mono);font-size:12px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);padding:var(--dm-s-2) 10px;margin:var(--dm-s-1) 0 var(--dm-s-2);line-height:1.65}
.rtr-edit .a{color:var(--dm-add)}.rtr-edit .x{color:var(--dm-del);text-decoration:line-through;text-decoration-color:color-mix(in srgb,var(--dm-del) 40%,transparent)}
.rtr-src{display:flex;flex-wrap:wrap;gap:6px}
/* the plan's Clean marks and the closing foot strip are Clean's alone: Soft and Blueprint never show them */
.rtr-m,.rtr-ff{display:none}
/* Clean (owner, 18 Nov): a card of its own, bare or not: a hairline-outlined round card with the thinking head on top and
   a hairline under it. The plan's steps sit on a hairline rail that fills down into each step as the one above finishes;
   a finished step is a green disc whose tick draws in, the step in hand a calm ink spinner ring, a queued step a hairline
   circle. Notes and edits have no rail. The finished trail closes with an off-white foot strip that sums it up. The card
   grows with what it holds (grow()) and folds into its head. Content sits 16px in from every edge; the chevron's 28px
   circle sits 16px from the head's top, bottom and right edges (owner, 23 Nov) */
:root[data-style="clean"] .rtr.rtr.rtr,:root [data-style="clean"] .rtr.rtr.rtr,:root [data-style="clean"].rtr.rtr.rtr{padding:0;background:var(--dm-surface);box-shadow:var(--dm-shadow);border-radius:var(--dm-r-card);overflow:clip}
:root[data-style="clean"] .rtr.growing,:root [data-style="clean"] .rtr.growing,:root [data-style="clean"].rtr.growing{overflow-clip-margin:0px}
/* the chevron's 28px circle 16px from the head's top, bottom and right, as Web search's is (owner, 23 Nov) */
:root[data-style="clean"] .rtr-h,:root [data-style="clean"] .rtr-h,:root [data-style="clean"].rtr-h{min-height:calc(28px + 2 * var(--dm-strip-y));padding:0 23px 0 16px;gap:12px;border-radius:0;font-size:13.5px}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .rtr-h:hover,:root [data-style="clean"] .rtr-h:hover,:root [data-style="clean"].rtr-h:hover{background:none}}
:root[data-style="clean"] .rtr-h:focus-visible,:root [data-style="clean"] .rtr-h:focus-visible,:root [data-style="clean"].rtr-h:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-card)}
/* the head's 14px mark sits centred on the steps' 16px marks, and its words start where theirs do (44px in) */
:root[data-style="clean"] .rtr-mark,:root [data-style="clean"] .rtr-mark,:root [data-style="clean"].rtr-mark{color:var(--dm-fg);margin:0 1px}
:root[data-style="clean"] .rtr-title,:root [data-style="clean"] .rtr-title,:root [data-style="clean"].rtr-title{font-weight:500}
:root[data-style="clean"] .rtr-title:not(.shim),:root [data-style="clean"] .rtr-title:not(.shim),:root [data-style="clean"].rtr-title:not(.shim){color:var(--dm-fg)}
:root[data-style="clean"] .rtr-time,:root [data-style="clean"] .rtr-time,:root [data-style="clean"].rtr-time{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .rtr-chev,:root [data-style="clean"] .rtr-chev,:root [data-style="clean"].rtr-chev{width:14px;height:14px;border-radius:50%;box-shadow:0 0 0 7px transparent;transition:transform .4s var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .rtr-h:hover .rtr-chev,:root [data-style="clean"] .rtr-h:hover .rtr-chev,:root [data-style="clean"].rtr-h:hover .rtr-chev{background:var(--dm-row);box-shadow:0 0 0 7px var(--dm-row);color:var(--dm-fg)}}
/* (its press, the motion pieces' .mx-press: in Clean, where the header's hover is the chevron's fill, the press deepens that fill) */
:root[data-style="clean"] .rtr-h.mx-press:active,:root [data-style="clean"] .rtr-h.mx-press:active,:root [data-style="clean"].rtr-h.mx-press:active{background:none}
:root[data-style="clean"] .rtr-h:active .rtr-chev,:root [data-style="clean"] .rtr-h:active .rtr-chev,:root [data-style="clean"].rtr-h:active .rtr-chev{background:var(--dm-row-press);box-shadow:0 0 0 7px var(--dm-row-press);transition-duration:var(--dm-t-press)}
:root[data-style="clean"] .rtr-body,:root [data-style="clean"] .rtr-body,:root [data-style="clean"].rtr-body{padding:10px 16px;border-top:1px solid var(--dm-line)}
:root[data-style="clean"] .rtr-body[data-v="sources"],:root [data-style="clean"] .rtr-body[data-v="sources"],:root [data-style="clean"].rtr-body[data-v="sources"]{padding:16px}
:root[data-style="clean"] .rtr-li,:root [data-style="clean"] .rtr-li,:root [data-style="clean"].rtr-li{padding:6px 0 6px 28px;line-height:20px}
:root[data-style="clean"] .rtr-li .g,:root [data-style="clean"] .rtr-li .g,:root [data-style="clean"].rtr-li .g{top:8px}
:root[data-style="clean"] .rtr-li .d,:root [data-style="clean"] .rtr-li .d,:root [data-style="clean"].rtr-li .d{line-height:18px;margin-top:0}
/* the rail: a hairline from under each mark to just above the next, and over it the part that has filled */
:root[data-style="clean"] .rtr-li:not(:last-child)::before,:root [data-style="clean"] .rtr-li:not(:last-child)::before,:root [data-style="clean"].rtr-li:not(:last-child)::before{top:28px;bottom:-4px;background:var(--dm-line)}
:root[data-style="clean"] .rtr-body:not([data-v="plan"]) .rtr-li::before,:root [data-style="clean"] .rtr-body:not([data-v="plan"]) .rtr-li::before,:root [data-style="clean"].rtr-body:not([data-v="plan"]) .rtr-li::before{display:none}
:root[data-style="clean"] .rtr-body[data-v="plan"] .rtr-li:not(:last-child)::before,:root [data-style="clean"] .rtr-body[data-v="plan"] .rtr-li:not(:last-child)::before,:root [data-style="clean"].rtr-body[data-v="plan"] .rtr-li:not(:last-child)::before{background:var(--dm-line) linear-gradient(var(--dm-line-strong),var(--dm-line-strong)) no-repeat 0 0/100% 0}
:root[data-style="clean"] .rtr-body[data-v="plan"] .rtr-li[data-s="done"]:not(:last-child)::before,:root [data-style="clean"] .rtr-body[data-v="plan"] .rtr-li[data-s="done"]:not(:last-child)::before,:root [data-style="clean"].rtr-body[data-v="plan"] .rtr-li[data-s="done"]:not(:last-child)::before{background-size:100% 100%}
/* the marks */
/* (React sets its own display on Soft's tick, so this one has to win over an inline style) */
:root[data-style="clean"] .rtr-body[data-v="plan"] .g>:not(.rtr-m),:root [data-style="clean"] .rtr-body[data-v="plan"] .g>:not(.rtr-m),:root [data-style="clean"].rtr-body[data-v="plan"] .g>:not(.rtr-m){display:none!important}
:root[data-style="clean"] .rtr-m,:root [data-style="clean"] .rtr-m,:root [data-style="clean"].rtr-m{display:grid;place-items:center;width:16px;height:16px;box-sizing:border-box;border-radius:50%}
:root[data-style="clean"] [data-s="next"]>.g>.rtr-m,:root [data-style="clean"] [data-s="next"]>.g>.rtr-m,:root [data-style="clean"][data-s="next"]>.g>.rtr-m{box-shadow:inset 0 0 0 1px var(--dm-line-strong)}
:root[data-style="clean"] [data-s="now"]>.g>.rtr-m,:root [data-style="clean"] [data-s="now"]>.g>.rtr-m,:root [data-style="clean"][data-s="now"]>.g>.rtr-m{border:1.5px solid var(--dm-line);border-top-color:var(--dm-fg);animation:rot .9s linear infinite}
:root[data-style="clean"] [data-s="done"]>.g>.rtr-m,:root [data-style="clean"] [data-s="done"]>.g>.rtr-m,:root [data-style="clean"][data-s="done"]>.g>.rtr-m{background:var(--dm-ok-mark);color:var(--dm-surface)}
:root[data-style="clean"] .rtr-m svg,:root [data-style="clean"] .rtr-m svg,:root [data-style="clean"].rtr-m svg,:root[data-style="clean"] .rtr-fk svg,:root [data-style="clean"] .rtr-fk svg,:root [data-style="clean"].rtr-fk svg{width:10px;height:10px;fill:none;stroke:currentColor;stroke-width:3.2;stroke-linecap:round;stroke-linejoin:round}
/* the moment a step finishes: its disc settles in and its tick draws, the rail draws down into the next step, and that
   step's queued ring turns into the spinner as the rail reaches it */
@keyframes rtrdisc{from{opacity:0;transform:scale(.5)}}
@keyframes rtrdraw{to{stroke-dashoffset:0}}
@keyframes rtrfill{from{background-size:100% 0}}
@keyframes rtrnow{from{border-color:var(--dm-line-strong)}}
:root[data-style="clean"] .rtr-li.just>.g>.rtr-m,:root [data-style="clean"] .rtr-li.just>.g>.rtr-m,:root [data-style="clean"].rtr-li.just>.g>.rtr-m{animation:rtrdisc .34s var(--dm-ease) backwards}
:root[data-style="clean"] .rtr-li.just>.g>.rtr-m path,:root [data-style="clean"] .rtr-li.just>.g>.rtr-m path,:root [data-style="clean"].rtr-li.just>.g>.rtr-m path{stroke-dasharray:1;stroke-dashoffset:1;animation:rtrdraw .3s var(--dm-ease) .14s forwards}
:root[data-style="clean"] .rtr-body[data-v="plan"] .rtr-li.just:not(:last-child)::before,:root [data-style="clean"] .rtr-body[data-v="plan"] .rtr-li.just:not(:last-child)::before,:root [data-style="clean"].rtr-body[data-v="plan"] .rtr-li.just:not(:last-child)::before{animation:rtrfill .44s var(--dm-ease-io) .2s backwards}
:root[data-style="clean"] .rtr-li.next-in>.g>.rtr-m,:root [data-style="clean"] .rtr-li.next-in>.g>.rtr-m,:root [data-style="clean"].rtr-li.next-in>.g>.rtr-m{animation:rtrnow .3s var(--dm-ease) .5s backwards,rot .9s linear infinite}
:root[data-style="clean"] .rtr-src,:root [data-style="clean"] .rtr-src,:root [data-style="clean"].rtr-src{gap:8px}
:root[data-style="clean"] .rtr-body[data-v="edits"] .g,:root [data-style="clean"] .rtr-body[data-v="edits"] .g,:root [data-style="clean"].rtr-body[data-v="edits"] .g{color:var(--dm-muted)}
:root[data-style="clean"] .rtr-edit,:root [data-style="clean"] .rtr-edit,:root [data-style="clean"].rtr-edit{border-radius:var(--dm-r-box);margin:4px 0 8px;padding:8px 12px;line-height:20px}
:root[data-style="clean"] .rtr-body>.rtr-edit:last-child,:root [data-style="clean"] .rtr-body>.rtr-edit:last-child,:root [data-style="clean"].rtr-body>.rtr-edit:last-child,:root[data-style="clean"] .rtr-body>:last-child>.rtr-edit:last-child,:root [data-style="clean"] .rtr-body>:last-child>.rtr-edit:last-child,:root [data-style="clean"].rtr-body>:last-child>.rtr-edit:last-child{margin-bottom:6px}
/* the foot strip, once the trail is done: a green tick, how much of the plan is done, and what it read and changed */
:root[data-style="clean"] .rtr-ff,:root [data-style="clean"] .rtr-ff,:root [data-style="clean"].rtr-ff{display:grid}
:root[data-style="clean"] .rtr-f,:root [data-style="clean"] .rtr-f,:root [data-style="clean"].rtr-f{display:flex;align-items:center;gap:12px;min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);margin:0;padding:0 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);font-size:12.5px;color:var(--dm-fg2);white-space:nowrap}
/* (the foot's tick is a done step's mark: the same 16px disc on the same column, its words where the steps' words start) */
:root[data-style="clean"] .rtr-fk,:root [data-style="clean"] .rtr-fk,:root [data-style="clean"].rtr-fk{display:grid;place-items:center;width:16px;height:16px;flex:none;border-radius:50%;background:var(--dm-ok-mark);color:var(--dm-surface)}
:root[data-style="clean"] .rtr-fs,:root [data-style="clean"] .rtr-fs,:root [data-style="clean"].rtr-fs{margin-left:auto;color:var(--dm-muted);overflow:hidden;text-overflow:ellipsis}
@media (prefers-reduced-motion:reduce){:root[data-style="clean"] .rtr-li:is(.just,.next-in) *,:root [data-style="clean"] .rtr-li:is(.just,.next-in) *,:root [data-style="clean"].rtr-li:is(.just,.next-in) *,:root[data-style="clean"] .rtr-li.just::before,:root [data-style="clean"] .rtr-li.just::before,:root [data-style="clean"].rtr-li.just::before{animation:none!important}:root[data-style="clean"] .rtr-li.just>.g>.rtr-m path,:root [data-style="clean"] .rtr-li.just>.g>.rtr-m path,:root [data-style="clean"].rtr-li.just>.g>.rtr-m path{stroke-dashoffset:0}:root[data-style="clean"] [data-s="now"]>.g>.rtr-m,:root [data-style="clean"] [data-s="now"]>.g>.rtr-m,:root [data-style="clean"][data-s="now"]>.g>.rtr-m{animation:none}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, REDUCE, enter, grow, reflow, seg, showTip, stagger, swap, tipFor } from '../core/core.js';
DM.def('reasoning-trail', (r, c) => {
  const body = $('.rtr-body', r), head = $('.rtr-h', r), fold = $('.rtr-fold', r), title = $('.rtr-title', r), time = $('.rtr-time', r), mark = $('.rtr-mark', r);
  const rtr = $('.rtr', r), main = rtr.closest('.dm-main');
  let tab = 'plan', secs = 0, just = -1;
  const plan = [['Open the onboarding file','4 frames'],['Compare it with the design system','12 components'],['Find spacing that breaks the 8px grid','3 frames'],['Draft fixes for review','Ready']];
  const NOTES = ['The hero card uses 20px padding, every other card uses 24px.','Mobile frames already follow the grid, desktop drifted.','Two buttons use a hard-coded grey instead of a token.'];
  // each source's chip, and its tip while the agent reads it, once it has read it, and (Card.tsx) once it has edited it
  const SRC = [
    { k:'fig', mark:I('figma','xs'), label:'Onboarding.fig', reading:'Reading the frames in Figma', read:'Figma, 4 frames read' },
    { k:'ts', mark:'<span class="ft">TS</span>', label:'tokens.ts', reading:'Reading src/styles/tokens.ts', read:'src/styles/tokens.ts, 212 lines' },
    { k:'tsx', mark:'<span class="ft re">TSX</span>', label:'Card.tsx', reading:'Reading src/components/Card.tsx', read:'src/components/Card.tsx', edited:'src/components/Card.tsx, 2 edits' },
    { k:'web', mark:I('globe','xs'), label:'Spacing guide', reading:'Reading designme.dev/guide/spacing', read:'designme.dev/guide/spacing' }
  ];
  const EDITS = [
    `<div class="rtr-li" data-key="e0"><span class="g">${I('edit','xs')}</span><span>Card.tsx<span class="d">2 lines</span></span></div><div class="rtr-edit" data-key="e0d"><div class="x">padding: 20px;</div><div class="a">padding: var(--space-6);</div></div>`,
    `<div class="rtr-li" data-key="e1"><span class="g">${I('edit','xs')}</span><span>Button.tsx<span class="d">1 line</span></span></div><div class="rtr-edit" data-key="e1d"><div class="x">color: #8a8a8a;</div><div class="a">color: var(--text-dim);</div></div>`
  ];
  // where the run is: the plan steps done, the notes found (by their place in NOTES), each source's state (unread,
  // 'reading', 'read' or 'edited') and the edits drafted. Every view shows only what the run has made by then; END is
  // the finished trail
  const now = { done:0, end:false, notes:[], src:['reading'], edits:0 };
  const END = { done:plan.length, end:true, notes:[0, 1, 2], src:['read', 'read', 'edited', 'read'], edits:2 };
  // a view with nothing in it yet says so, on the row the first one will take
  const none = what => `<div class="rtr-li" data-key="none"><span class="g"><span class="dot" style="color:var(--dm-faint)"></span></span><span class="muted">No ${what} yet</span></div>`;
  // each step carries Clean's own mark (.rtr-m) beside Soft's glyph; the style shows one of them. The step that has just
  // finished (just) and the one it hands on to play Clean's tick and rail once
  const tick = '<svg viewBox="0 0 24 24"><path pathLength="1" d="m5 12.5 4.5 4.5L19 7.5"/></svg>';
  const views = {
    plan: S => plan.map((p, i) => { const s = i < S.done ? 'done' : i === S.done && !S.end ? 'now' : 'next';
      return `<div class="rtr-li ${s === 'now' ? 'now' : ''}${i === just ? ' just' : ''}${i === just + 1 && s === 'now' ? ' next-in' : ''}" data-s="${s}"><span class="g">${i < S.done ? `<span style="color:var(--dm-ok)">${I('check','xs')}</span>` : i === S.done && !S.end ? '<span class="pulse"></span>' : '<span class="dot" style="color:var(--dm-faint)"></span>'}<span class="rtr-m" aria-hidden="true">${s === 'done' ? tick : ''}</span></span><span>${p[0]}<span class="d">${i < S.done ? p[1] : i === S.done && !S.end ? 'Working' : 'Next'}</span></span></div>`; }).join(''),
    notes: S => S.notes.length ? NOTES.map((t, i) => S.notes.includes(i) ? `<div class="rtr-li" data-key="n${i}"><span class="g"><span class="dot" style="color:var(--dm-faint)"></span></span><span>${t}</span></div>` : '').join('') : none('notes'),
    // a source the agent is still reading shimmers, as the header does while it thinks
    sources: S => S.src.some(Boolean) ? `<div class="rtr-src" data-key="src">${SRC.map((x, i) => { const s = S.src[i]; return s ? `<button class="fchip lnk" data-key="s-${x.k}" data-tip-at="below" data-tip="${x[s]}">${x.mark}${s === 'reading' ? `<span class="shim">${x.label}</span>` : x.label}</button>` : ''; }).join('')}</div>` : none('sources'),
    edits: S => S.edits ? EDITS.slice(0, S.edits).join('') : none('edits')
  };
  const paint = anim => { body.dataset.v = tab; body.innerHTML = views[tab](now); if (anim) stagger(Array.from(body.children), 50); };
  // the view's new markup laid over what is on screen: an element that stays (known by its data-key) is kept, so a tip
  // open on a chip stays open, and only what changed in it is redrawn; new ones go in where they belong and gone ones come
  // out. Returns the new ones
  const morph = markup => {
    const t = document.createElement('template'); t.innerHTML = markup; const fresh = [];
    const same = (e, n) => e.innerHTML === n.innerHTML && [...n.attributes].every(a => a.name === 'class' || a.name === 'style' || e.getAttribute(a.name) === a.value);
    const walk = (have, want) => {
      const old = new Map([...have.children].map(e => [e.dataset.key, e]));
      [...want.children].forEach((n, i) => {
        let e = old.get(n.dataset.key);
        if (e){ old.delete(n.dataset.key);
          if (n.querySelector('[data-key]')) walk(e, n);
          else if (!same(e, n)){ for (const a of n.attributes) if (a.name !== 'class' && a.name !== 'style') e.setAttribute(a.name, a.value); e.innerHTML = n.innerHTML; if (tipFor === e) showTip(e); }
        } else { e = n; fresh.push(e); }
